    "pv.kLang": "語言設定",
    "pv.vLang": "用語言切換揀嘅語言（한국어 · EN · 简中 · 繁中 · 日 · 粵），下次開就以嗰個語言顯示",
    "pv.kView": "顯示方式",
    "pv.vView": "茶百科同商店用單欄列表定雙欄格仔顯示",
    "pv.kPosts": "社群貼文",
    "pv.vPosts": "送出咗貼文嘅本機副本——暱稱、貼文類型、評分、茶或茶包名、正文、發布時間",
    "pv.kReacts": "讚同有幫助",
    "pv.vReacts": "你對邊啲貼文撳過讚或者有幫助（淨係喺本機計）",
    "pv.kApps": "登記申請",
    "pv.vApps": "送出咗申請嘅本機副本——舖頭名、聯絡人、聯絡方法、地址、菜單、營業時間、社群或地圖連結、備註",
    "pv.kMember": "會員等級",
    "pv.vMember": "Google Play 確認嘅訂閱等級同訂閱咗嘅商品 ID",
    "pv.s2.note": "本機存嘅嘢隨時可以喺應用入面睇返、刪除；刪應用或者清除瀏覽器入面呢個網站嘅資料就會一齊刪。已經送去伺服器嘅貼文同申請，清咗本機資料之後仍然留喺伺服器，想一齊刪就照第10節嘅方法提出。",
    "pv.s3.title": "伺服器上資料嘅公開同保存",
    "pv.s3.body": "社群貼文係以公開為前提收集。營運者確認同發布之後，其他用戶就睇到，公開定收起由營運者決定。茶館入駐申請、廠商商品登記同新茶包登記淨係營運者睇，審核完淨係將舖頭同商品資料加入應用。伺服器上嘅資料會喺審核同發布需要嘅期間保存；如果你照第10節嘅方法提出刪除，我哋確認之後會即刻刪。",
    "pv.s4.title": "為咗離線用而暫時保存",
    "pv.s4.body": "為咗冇網絡都用得，茶基百科會透過 Service Worker 將應用嘅畫面檔案（HTML、CSS、JS、圖示）暫時存喺部機瀏覽器嘅快取。嗰啲淨係應用本身嘅副本，唔係用戶嘅個人資料或者紀錄。應用更新嗰陣畫面檔案會自動換做最新版本。",
    "pv.s5.title": "裝置權限",
    "pv.s5.body": "茶基百科 <span class=\"key\">唔會要求任何裝置權限</span>——相機、收音咪、位置、通訊錄、相片、通知、儲存空間全部都唔要求。智能鏡頭撳「影相」會開部機嘅相機應用，撳「揀相」會開檔案選擇器，應用淨係收到一張相；張相淨係喺部機讀嚟睇條碼，唔會存入應用，亦唔會送去伺服器。計時完淨係喺應用畫面用顯示同提示聲通知，唔會發推送或者背景通知。",
    "pv.s6.title": "應用內定期訂閱同付款",
    "pv.s6.body": "個人會員、茶館會員、廠商會員嘅月費經 Google Play 應用內購買處理。付款方法同卡資料由 Google Play 處理，茶基百科唔會直接收或者存卡號。應用淨係讀 Google Play 講嘅訂閱狀態（買咗邊個商品、仲有冇效）嚟開會員等級，再將呢個等級存喺部機。取消訂閱同退款跟 Google Play 嘅政策同流程。",
    "pv.s7.title": "外部連結同 Coupang 合作夥伴",
    "pv.s7.body": "應用入面有去 Naver 地圖（香港茶）、Upaper 電子書店、YouTube playlist（茶貓茶館BGM），仲有合作茶館嘅 Naver、Kakao、Google 地圖連結。商店畫面亦有去 Coupang 商品或者搜尋結果嘅推廣連結。撳咗連結之後由你嘅瀏覽器開嗰個網站，之後就跟嗰個網站嘅私隱政策，茶基百科唔會將用戶資料交畀嗰個網站。",
    "pv.s7.note": "呢篇貼文係 Coupang 合作夥伴活動嘅一部分，我哋會因此收到一筆佣金。",
    "pv.s8.title": "第三方提供同委託處理",
    "pv.s8.body": "茶基百科為咗伺服器儲存同付款，將處理委託畀下面嘅公司。唔會賣用戶資料，亦都唔會用喺目的以外嘅用途。",
    "pv.s8.supabase": "<span class=\"key\">Supabase Inc.</span> —— 保存社群貼文同登記申請（資料庫託管）。伺服器區域係大韓民國（首爾）。",
    "pv.s8.google": "<span class=\"key\">Google LLC</span> —— Google Play 應用內購買同訂閱狀態確認。",
    "pv.s9.title": "小朋友嘅私隱",
    "pv.s9.body": "茶基百科唔會明知而收集未滿14歲小朋友嘅個人資料。社群淨係叫人填暱稱，亦都提醒唔好喺貼文寫真名、聯絡方法或者地址。如果監護人知道小朋友送出嘅貼文或者申請存咗喺伺服器，可以照第12節嘅聯絡方法要求刪除，我哋確認之後會即刻刪。",
    "pv.s10.title": "用戶嘅權利同刪除要求",
    "pv.s10.body": "用戶隨時可以喺應用嘅品茶筆記畫面睇返自己寫嘅紀錄，逐條刪除。如果想一次清晒本機存嘅嘢，喺瀏覽器刪咗呢個網站嘅資料或者刪咗應用就得。想刪伺服器上嘅社群貼文或者登記申請，就寫信去 rotroka@gmail.com，講明貼文嘅暱稱同發布時間，或者申請嘅舖頭名。由於冇帳號，有需要嘅話我哋會另外問你攞最少嘅確認資料。",
    "pv.s11.title": "政策嘅變更",
    "pv.s11.body": "應用功能有變而要改呢份政策，會先喺呢頁公布新政策同生效日。如果變更會新增收集個人資料或者新增送去伺服器嘅項目，亦會喺應用入面通知。",
    "pv.s12.title": "聯絡",
    "pv.s12.body": "對呢份私隱政策有疑問或者想要求刪除，可以透過下面嘅方法聯絡我哋。",
