    "pv.vPosts": "สำเนาบนอุปกรณ์ของคุณของสิ่งที่คุณส่ง — ชื่อเล่น ประเภทโพสต์ คะแนน ชื่อชาหรือชาถุง เนื้อหา เวลาที่เขียน",
