    "pv.vLang": "Ngôn ngữ bạn chọn bằng nút chuyển ngôn ngữ (tiếng Hàn, tiếng Anh, tiếng Trung giản thể hoặc phồn thể, tiếng Nhật, tiếng Quảng Đông), để ứng dụng mở bằng ngôn ngữ đó lần sau",
